#pragma once

#include "data/sha256.hpp"
#include "engine/native_runtime_memory.hpp"

#include <algorithm>
#include <array>
#include <cstdint>
#include <map>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

namespace eon {

// These values and guest pointers are generated by Eon's bounded compatibility
// policy. They are not observed Exec returns and do not model Kickstart's
// scheduler, device internals, or ROM execution.
enum class DeuterosAmigaExecCompatibilityOrigin : std::uint8_t {
    eon_native_compatibility,
};

struct DeuterosAmigaExecCompatibilityGraph {
    std::uint64_t runtime_generation = 0;
    std::uint32_t exec_base_address = 0;
    std::uint32_t task_address = 0;
    std::uint32_t trackdisk_device_address = 0;
    DeuterosAmigaExecCompatibilityOrigin origin =
        DeuterosAmigaExecCompatibilityOrigin::eon_native_compatibility;
};

// The bootstrap may need ExecBase only to reach its explicitly serviced
// OpenLibrary call. This pointer is an Eon virtual token, not a guest ROM or
// observed Kickstart address and does not install any Exec structures.
struct DeuterosAmigaExecCompatibilityPointer {
    std::uint64_t runtime_generation = 0;
    std::uint32_t pointer_cell = 4;
    std::uint32_t virtual_exec_base = 0;
    DeuterosAmigaExecCompatibilityOrigin origin =
        DeuterosAmigaExecCompatibilityOrigin::eon_native_compatibility;
};

struct DeuterosAmigaExecCompatibilityTaskResult {
    std::uint64_t runtime_generation = 0;
    std::uint64_t service_sequence = 0;
    std::uint32_t call_address = 0;
    std::uint32_t task_address = 0;
    DeuterosAmigaExecCompatibilityOrigin origin =
        DeuterosAmigaExecCompatibilityOrigin::eon_native_compatibility;
};

struct DeuterosAmigaExecCompatibilityPortResult {
    std::uint64_t runtime_generation = 0;
    std::uint64_t service_sequence = 0;
    std::uint32_t call_address = 0;
    std::uint32_t port_address = 0;
    std::uint32_t task_address = 0;
    DeuterosAmigaExecCompatibilityOrigin origin =
        DeuterosAmigaExecCompatibilityOrigin::eon_native_compatibility;
};

struct DeuterosAmigaExecCompatibilityOpenResult {
    std::uint64_t runtime_generation = 0;
    std::uint64_t service_sequence = 0;
    std::uint32_t call_address = 0;
    std::uint32_t request_address = 0;
    std::uint32_t device_address = 0;
    std::uint32_t unit_address = 0;
    std::uint8_t unit = 0;
    std::uint8_t service_generated_io_error = 0;
    DeuterosAmigaExecCompatibilityOrigin origin =
        DeuterosAmigaExecCompatibilityOrigin::eon_native_compatibility;
};

// A deliberately narrow virtual Exec/trackdisk graph for the recovered
// Deuteros title setup calls. Guest-visible objects use an Eon-reserved 24-bit
// range. Exact FindTask(NULL), AddPort, and OpenDevice call sites are admitted
// in order; all generated values are separately tagged as Eon compatibility.
// The class does not execute ROM code or claim Exec/trackdisk internals.
class DeuterosAmigaExecCompatibilitySession {
public:
    static constexpr std::uint32_t guest_range_begin = 0x00d00000U;
    static constexpr std::uint32_t guest_range_end = 0x00d01000U;
    static constexpr std::uint32_t exec_base_address = 0x00d00000U;
    static constexpr std::uint32_t task_address = 0x00d00200U;
    static constexpr std::uint32_t trackdisk_device_address = 0x00d00300U;
    static constexpr std::uint32_t unit0_address = 0x00d00400U;
    static constexpr std::uint32_t unit1_address = 0x00d00600U;
    static constexpr std::uint32_t exec_base_pointer_cell = 0x00000004U;
    static constexpr std::uint32_t this_task_offset = 0x0114U;
    static constexpr std::uint32_t device_list_offset = 0x015eU;
    static constexpr std::uint32_t port_list_offset = 0x0188U;
    static constexpr std::uint32_t device_open_count_offset = 0x0020U;
    static constexpr std::uint32_t device_unit_table_offset = 0x0024U;
    static constexpr std::uint32_t unit_open_count_offset = 0x0024U;

    explicit DeuterosAmigaExecCompatibilitySession(
        const std::uint64_t runtime_generation) noexcept
        : runtime_generation_(runtime_generation) {}

    [[nodiscard]] std::optional<DeuterosAmigaExecCompatibilityPointer>
    install_bootstrap_exec_base_pointer(NativeRuntimeMemory& memory) {
        if (!valid_generation() || graph_installed_
            || !range_uninitialized(memory, exec_base_pointer_cell,
                exec_base_pointer_cell + 4U)) {
            return std::nullopt;
        }
        NativeRuntimeEffectBatch batch{
            "deuteros-amiga-eon-bootstrap-execbase-pointer-"
                + std::to_string(runtime_generation_), true,
            {{1, {NativeRuntimeAddressSpace::linear, std::nullopt,
                    exec_base_pointer_cell},
                MemoryTransferElementWidth::longword,
                NativeRuntimeByteOrder::big_endian, exec_base_address}}};
        if (!memory.apply(batch).accepted) return std::nullopt;
        bootstrap_exec_base_pointer_installed_ = true;
        return DeuterosAmigaExecCompatibilityPointer{
            runtime_generation_, exec_base_pointer_cell, exec_base_address};
    }

    [[nodiscard]] std::optional<DeuterosAmigaExecCompatibilityGraph>
    install_graph(NativeRuntimeMemory& memory) {
        const auto existing_exec_base = read_be32(memory, exec_base_pointer_cell);
        const bool pointer_available = !existing_exec_base
            ? range_uninitialized(memory, exec_base_pointer_cell,
                exec_base_pointer_cell + 4U)
            : *existing_exec_base == exec_base_address;
        if (!valid_generation() || graph_installed_
            || guest_range_end > 0x01000000U
            || !range_uninitialized(memory, guest_range_begin, guest_range_end)
            || !pointer_available) {
            return std::nullopt;
        }
        const auto title_setup = memory.read_linear_range(title_setup_source_address,
            title_setup_source_size);
        if (!title_setup || to_hex(sha256(*title_setup)) != title_setup_source_sha256) {
            return std::nullopt;
        }

        std::map<std::uint32_t, std::uint8_t> writes;
        if (!existing_exec_base) put32(writes, exec_base_pointer_cell, exec_base_address);
        put32(writes, exec_base_address + this_task_offset, task_address);

        // Valid Exec List headers: head points to the tail sentinel, tail is
        // NULL, and tailpred points back to the head field.
        initialize_empty_list(writes, exec_base_address + device_list_offset);
        initialize_empty_list(writes, exec_base_address + port_list_offset);

        // The Eon-owned current-task record is sufficient for the exact
        // mp_SigTask pointers below. It is not linked into a simulated task
        // scheduler and must not be treated as a real Exec Task.
        put32(writes, task_address, 0);
        put32(writes, task_address + 4U, 0);
        put8(writes, task_address + 8U, 1); // NT_TASK
        put8(writes, task_address + 9U, 0);
        put32(writes, task_address + 10U, 0);

        // DeviceList contains one Eon virtual trackdisk node so the bounded
        // OpenDevice calls can resolve the original name through owned state.
        const auto device_list = exec_base_address + device_list_offset;
        const auto device_tail_sentinel = device_list + 4U;
        put32(writes, trackdisk_device_address, device_tail_sentinel);
        put32(writes, trackdisk_device_address + 4U, device_list);
        put8(writes, trackdisk_device_address + 8U, 3); // NT_DEVICE
        put8(writes, trackdisk_device_address + 9U, 0);
        put32(writes, trackdisk_device_address + 10U, title_device_name_address);
        put32(writes, device_list, trackdisk_device_address);
        put32(writes, device_list + 8U, trackdisk_device_address);
        put16(writes, trackdisk_device_address + device_open_count_offset, 0);
        put32(writes, trackdisk_device_address + device_unit_table_offset, 0);
        put32(writes, trackdisk_device_address + device_unit_table_offset + 4U, 0);

        if (!apply_writes(memory,
                "deuteros-amiga-exec-compat-graph-" + std::to_string(runtime_generation_),
                writes)) {
            return std::nullopt;
        }
        graph_installed_ = true;
        return DeuterosAmigaExecCompatibilityGraph{runtime_generation_,
            exec_base_address, task_address, trackdisk_device_address};
    }

    [[nodiscard]] std::optional<DeuterosAmigaExecCompatibilityTaskResult>
    find_current_task(const std::uint32_t exec_base_source_address,
        const std::uint32_t call_address, const std::int16_t vector,
        const std::uint32_t return_address, const std::uint32_t name_address) noexcept {
        if (!valid_generation() || !graph_installed_ || task_found_
            || exec_base_source_address != exec_base_pointer_cell
            || call_address != 0x206deU || vector != -0x126
            || return_address != 0x206e2U || name_address != 0) {
            return std::nullopt;
        }
        task_found_ = true;
        return DeuterosAmigaExecCompatibilityTaskResult{
            runtime_generation_, next_sequence(), call_address, task_address};
    }

    [[nodiscard]] std::optional<DeuterosAmigaExecCompatibilityTaskResult>
    find_main_stage_task(const std::uint32_t exec_base_source_address,
        const std::uint32_t call_address, const std::int16_t vector,
        const std::uint32_t return_address, const std::uint32_t name_address) noexcept {
        if (!valid_generation() || !graph_installed_ || !task_found_
            || main_stage_task_found_ || exec_base_source_address != exec_base_pointer_cell
            || call_address != 0x2099eU || vector != -0x126
            || return_address != 0x209a2U || name_address != 0) return std::nullopt;
        main_stage_task_found_ = true;
        return DeuterosAmigaExecCompatibilityTaskResult{
            runtime_generation_, next_sequence(), call_address, task_address};
    }

    [[nodiscard]] std::optional<DeuterosAmigaExecCompatibilityPortResult>
    add_title_port(NativeRuntimeMemory& memory,
        const std::uint32_t exec_base_source_address,
        const std::uint32_t call_address, const std::int16_t vector,
        const std::uint32_t return_address, const std::uint32_t port_address) {
        if (!valid_generation() || !graph_installed_ || !task_found_
            || exec_base_source_address != exec_base_pointer_cell || vector != -0x162
            || (call_address == 0x2070cU
                && (return_address != 0x20710U || port_address != title_port1_address
                    || ports_added_ != 0 || units_opened_ != 0))
            || (call_address == 0x2077aU
                && (return_address != 0x2077eU || port_address != title_port2_address
                    || ports_added_ != 1 || units_opened_ != 1))
            || (call_address != 0x2070cU && call_address != 0x2077aU)) {
            return std::nullopt;
        }
        const auto name = memory.read_linear_range(title_device_name_address, 17);
        const auto port_preimage = memory.read_linear_range(port_address, 0x20);
        if (!name || !std::equal(name->begin(), name->end(),
                title_device_name_bytes.begin(), title_device_name_bytes.end())
            || !port_preimage
            || !all_zero(*port_preimage)
            || !list_is_valid(memory, exec_base_address + port_list_offset)) {
            return std::nullopt;
        }

        std::map<std::uint32_t, std::uint8_t> writes;
        // The local title stores the MsgPort Node fields before calling
        // AddPort. Offsets follow exec/nodes.h and exec/ports.h.
        put8(writes, port_address + 8U, 4); // NT_MSGPORT
        put8(writes, port_address + 9U, 0x7f);
        put32(writes, port_address + 10U, title_device_name_address);
        put8(writes, port_address + 15U, 1); // mp_SigBit
        put32(writes, port_address + 16U, task_address); // Eon Task pointer

        // Kickstart 1.3 AddPort's bounded effect: NEWLIST(mp_MsgList), then
        // Enqueue by signed ln_Pri, inserting after equal-priority nodes.
        const auto port_message_list = port_address + 0x14U;
        initialize_empty_list(writes, port_message_list);
        if (!enqueue_node(memory, writes,
                exec_base_address + port_list_offset, port_address,
                static_cast<std::int8_t>(0x7f))) {
            return std::nullopt;
        }
        if (!apply_writes(memory, "deuteros-amiga-exec-compat-addport-"
                + std::to_string(runtime_generation_) + "-"
                + std::to_string(ports_added_ + 1U), writes)) {
            return std::nullopt;
        }
        ++ports_added_;
        return DeuterosAmigaExecCompatibilityPortResult{
            runtime_generation_, next_sequence(), call_address, port_address,
            task_address};
    }

    [[nodiscard]] std::optional<DeuterosAmigaExecCompatibilityOpenResult>
    open_title_trackdisk_unit(NativeRuntimeMemory& memory,
        const std::uint32_t exec_base_source_address,
        const std::uint32_t call_address, const std::int16_t vector,
        const std::uint32_t return_address, const std::uint32_t name_address,
        const std::string_view device_name, const std::uint32_t request_address,
        const std::uint32_t reply_port_address, const std::uint32_t unit,
        const std::uint32_t flags) {
        const bool first = call_address == 0x20732U && return_address == 0x20736U
            && request_address == title_request1_address
            && reply_port_address == title_port1_address && unit == 0
            && ports_added_ == 1 && units_opened_ == 0;
        const bool second = call_address == 0x207a0U && return_address == 0x207a4U
            && request_address == title_request2_address
            && reply_port_address == title_port2_address && unit == 1
            && ports_added_ == 2 && units_opened_ == 1;
        if (!valid_generation() || !graph_installed_ || !task_found_
            || exec_base_source_address != exec_base_pointer_cell
            || vector != -0x1bc || name_address != title_device_name_address
            || device_name != "trackdisk.device" || flags != 0 || (!first && !second)) {
            return std::nullopt;
        }
        const auto name = memory.read_linear_range(title_device_name_address, 17);
        const auto request = memory.read_linear_range(request_address, 0x34);
        const auto public_ports = memory.read_linear_range(
            exec_base_address + port_list_offset, 12);
        if (!name || !std::equal(name->begin(), name->end(),
                title_device_name_bytes.begin(), title_device_name_bytes.end())
            || !request
            || !public_ports || !port_is_public(memory, reply_port_address)
            || !read_be32(memory, request_address + 0x14U).has_value()
            || read_be32(memory, request_address + 0x14U) != 0
            || read_be32(memory, request_address + 0x18U) != 0
            || memory.read_byte({NativeRuntimeAddressSpace::linear, std::nullopt,
                request_address + 0x1fU}) != std::optional<std::uint8_t>{0}) {
            return std::nullopt;
        }

        const auto unit_address = unit == 0 ? unit0_address : unit1_address;
        const auto request_cell = unit == 0 ? 0x20698U : 0x2069cU;
        const auto cell_before = read_be32(memory, request_cell);
        const auto reply_before = read_be32(memory, request_address + 0x0eU);
        const auto device_open_count = read_be16(memory,
            trackdisk_device_address + device_open_count_offset);
        const auto unit_table_cell = trackdisk_device_address
            + device_unit_table_offset + unit * 4U;
        if (!cell_before || *cell_before != 0 || !reply_before || *reply_before != 0
            || !device_open_count || *device_open_count != units_opened_
            || read_be32(memory, unit_table_cell) != 0
            || read_be16(memory, unit_address + unit_open_count_offset).value_or(0) != 0) {
            return std::nullopt;
        }

        std::map<std::uint32_t, std::uint8_t> writes;
        // These two pointer stores are the title's own setup instructions.
        put32(writes, request_cell, request_address);
        put32(writes, request_address + 0x0eU, reply_port_address);
        // This result is an Eon policy result, not an Exec or trackdisk ROM
        // return. The guest fields point only to the virtual Eon objects.
        put32(writes, request_address + 0x14U, trackdisk_device_address);
        put32(writes, request_address + 0x18U, unit_address);
        put8(writes, request_address + 0x1fU, 0); // native-service io_Error
        put16(writes, trackdisk_device_address + device_open_count_offset,
            static_cast<std::uint16_t>(units_opened_ + 1U));
        put32(writes, unit_table_cell, unit_address);
        put16(writes, unit_address + unit_open_count_offset, 1);

        if (!apply_writes(memory, "deuteros-amiga-exec-compat-open-"
                + std::to_string(runtime_generation_) + "-"
                + std::to_string(unit), writes)) {
            return std::nullopt;
        }
        ++units_opened_;
        return DeuterosAmigaExecCompatibilityOpenResult{
            runtime_generation_, next_sequence(), call_address, request_address,
            trackdisk_device_address, unit_address, static_cast<std::uint8_t>(unit), 0};
    }

    [[nodiscard]] std::optional<DeuterosAmigaExecCompatibilityPortResult>
    add_main_stage_port(NativeRuntimeMemory& memory,
        const std::uint32_t exec_base_source_address,
        const std::uint32_t call_address, const std::int16_t vector,
        const std::uint32_t return_address, const std::uint32_t port_address) {
        if (!valid_generation() || !graph_installed_ || !main_stage_task_found_
            || main_stage_port_added_ || exec_base_source_address != exec_base_pointer_cell
            || call_address != 0x209caU || vector != -0x162 || return_address != 0x209ceU
            || port_address != main_stage_port_address || ports_added_ != 2
            || units_opened_ != 2) return std::nullopt;
        const auto name_pointer = read_be32(memory, port_address + 10U);
        const auto name = name_pointer ? memory.read_linear_range(*name_pointer, 17) : std::nullopt;
        const auto port = memory.read_linear_range(port_address, 0x20U);
        if (!name_pointer || *name_pointer != main_stage_device_name_address || !name
            || !std::equal(name->begin(), name->end(), title_device_name_bytes.begin(),
                title_device_name_bytes.end())
            || !port || (*port)[8] != 4 || (*port)[9] != 0x7f || (*port)[15] != 1
            || read_be32(memory, port_address + 16U) != task_address
            || !all_zero(std::vector<std::uint8_t>(port->begin() + 0x14, port->end()))
            || !list_is_valid(memory, exec_base_address + port_list_offset)) {
            return std::nullopt;
        }
        std::map<std::uint32_t, std::uint8_t> writes;
        initialize_empty_list(writes, port_address + 0x14U);
        if (!enqueue_node(memory, writes, exec_base_address + port_list_offset,
                port_address, static_cast<std::int8_t>(0x7f))
            || !apply_writes(memory, "deuteros-amiga-exec-compat-main-stage-addport-"
                + std::to_string(runtime_generation_), writes)) return std::nullopt;
        ++ports_added_;
        main_stage_port_added_ = true;
        return DeuterosAmigaExecCompatibilityPortResult{
            runtime_generation_, next_sequence(), call_address, port_address, task_address};
    }

    [[nodiscard]] std::optional<DeuterosAmigaExecCompatibilityOpenResult>
    open_main_stage_trackdisk_unit(NativeRuntimeMemory& memory,
        const std::uint32_t exec_base_source_address,
        const std::uint32_t call_address, const std::int16_t vector,
        const std::uint32_t return_address, const std::uint32_t name_address,
        const std::uint32_t request_address, const std::uint32_t reply_port_address,
        const std::uint32_t unit, const std::uint32_t flags) {
        if (!valid_generation() || !graph_installed_ || !main_stage_port_added_
            || main_stage_unit_opened_ || exec_base_source_address != exec_base_pointer_cell
            || call_address != 0x209f0U || vector != -0x1bc || return_address != 0x209f4U
            || name_address != main_stage_device_name_address
            || request_address != main_stage_request_address
            || reply_port_address != main_stage_port_address || unit != 0 || flags != 0
            || ports_added_ != 3 || units_opened_ != 2) return std::nullopt;
        const auto name = memory.read_linear_range(name_address, 17U);
        const auto request = memory.read_linear_range(request_address, 0x34U);
        if (!name || !std::equal(name->begin(), name->end(), title_device_name_bytes.begin(),
                title_device_name_bytes.end())
            || !request || !port_is_public(memory, reply_port_address)
            || read_be32(memory, request_address + 0x0eU) != 0
            || read_be32(memory, request_address + 0x14U) != 0
            || read_be32(memory, request_address + 0x18U) != 0
            || memory.read_byte({NativeRuntimeAddressSpace::linear, std::nullopt,
                request_address + 0x1fU}) != std::optional<std::uint8_t>{0}
            || read_be32(memory, 0x20976U) != request_address
            || read_be32(memory, 0x2092aU) != reply_port_address
            || read_be16(memory, trackdisk_device_address + device_open_count_offset)
                != std::optional<std::uint16_t>{2}
            || read_be16(memory, unit0_address + unit_open_count_offset)
                != std::optional<std::uint16_t>{1}) return std::nullopt;
        std::map<std::uint32_t, std::uint8_t> writes;
        put32(writes, request_address + 0x0eU, reply_port_address);
        put32(writes, request_address + 0x14U, trackdisk_device_address);
        put32(writes, request_address + 0x18U, unit0_address);
        put8(writes, request_address + 0x1fU, 0);
        put16(writes, trackdisk_device_address + device_open_count_offset, 3);
        put16(writes, unit0_address + unit_open_count_offset, 2);
        if (!apply_writes(memory, "deuteros-amiga-exec-compat-main-stage-open-device-"
                + std::to_string(runtime_generation_), writes)) return std::nullopt;
        ++units_opened_;
        main_stage_unit_opened_ = true;
        return DeuterosAmigaExecCompatibilityOpenResult{runtime_generation_, next_sequence(),
            call_address, request_address, trackdisk_device_address, unit0_address, 0, 0};
    }

    [[nodiscard]] static constexpr std::uint32_t title_port1() noexcept {
        return title_port1_address;
    }
    [[nodiscard]] static constexpr std::uint32_t title_port2() noexcept {
        return title_port2_address;
    }
    [[nodiscard]] static constexpr std::uint32_t title_request1() noexcept {
        return title_request1_address;
    }
    [[nodiscard]] static constexpr std::uint32_t title_request2() noexcept {
        return title_request2_address;
    }

private:
    static constexpr std::uint64_t maximum_generation = 0x00ffffffffffffffULL;
    static constexpr std::uint32_t title_setup_source_address = 0x000206d4U;
    static constexpr std::uint32_t title_setup_source_size = 248U;
    static constexpr std::string_view title_setup_source_sha256 =
        "897622f29b8a4dcaa197101f7f25f2d564837525493faff82b071ebf5cd6286a";
    static constexpr std::uint32_t title_device_name_address = 0x000206acU;
    static constexpr std::array<std::uint8_t, 17> title_device_name_bytes{
        't','r','a','c','k','d','i','s','k','.','d','e','v','i','c','e',0};
    static constexpr std::uint32_t title_port1_address = 0x0002061cU;
    static constexpr std::uint32_t title_port2_address = 0x00020676U;
    static constexpr std::uint32_t title_request1_address = 0x000205e4U;
    static constexpr std::uint32_t title_request2_address = 0x0002063eU;
    static constexpr std::uint32_t main_stage_port_address = 0x00020954U;
    static constexpr std::uint32_t main_stage_request_address = 0x0002091cU;
    static constexpr std::uint32_t main_stage_device_name_address = 0x00020982U;

    [[nodiscard]] bool valid_generation() const noexcept {
        return runtime_generation_ != 0 && runtime_generation_ <= maximum_generation;
    }

    [[nodiscard]] std::uint64_t next_sequence() noexcept {
        return sequence_++;
    }

    [[nodiscard]] static bool range_uninitialized(const NativeRuntimeMemory& memory,
        const std::uint32_t begin, const std::uint32_t end) {
        for (const auto& cell : memory.checkpoint().initialized_bytes) {
            if (cell.location.address_space == NativeRuntimeAddressSpace::linear
                && !cell.location.segment && cell.location.offset >= begin
                && cell.location.offset < end) {
                return false;
            }
        }
        return true;
    }

    [[nodiscard]] static bool all_zero(const std::vector<std::uint8_t>& bytes) noexcept {
        for (const auto value : bytes) if (value != 0) return false;
        return true;
    }

    static void put8(std::map<std::uint32_t, std::uint8_t>& writes,
        const std::uint32_t address, const std::uint8_t value) {
        writes.emplace(address, value);
    }

    static void put16(std::map<std::uint32_t, std::uint8_t>& writes,
        const std::uint32_t address, const std::uint16_t value) {
        put8(writes, address, static_cast<std::uint8_t>(value >> 8U));
        put8(writes, address + 1U, static_cast<std::uint8_t>(value));
    }

    static void put32(std::map<std::uint32_t, std::uint8_t>& writes,
        const std::uint32_t address, const std::uint32_t value) {
        put8(writes, address, static_cast<std::uint8_t>(value >> 24U));
        put8(writes, address + 1U, static_cast<std::uint8_t>(value >> 16U));
        put8(writes, address + 2U, static_cast<std::uint8_t>(value >> 8U));
        put8(writes, address + 3U, static_cast<std::uint8_t>(value));
    }

    static void initialize_empty_list(std::map<std::uint32_t, std::uint8_t>& writes,
        const std::uint32_t address) {
        put32(writes, address, address + 4U);
        put32(writes, address + 4U, 0);
        put32(writes, address + 8U, address);
    }

    [[nodiscard]] static std::optional<std::uint32_t> read_be32(
        const NativeRuntimeMemory& memory, const std::uint32_t address) {
        const auto bytes = memory.read_linear_range(address, 4);
        if (!bytes) return std::nullopt;
        return (static_cast<std::uint32_t>((*bytes)[0]) << 24U)
            | (static_cast<std::uint32_t>((*bytes)[1]) << 16U)
            | (static_cast<std::uint32_t>((*bytes)[2]) << 8U)
            | static_cast<std::uint32_t>((*bytes)[3]);
    }

    [[nodiscard]] static std::optional<std::uint16_t> read_be16(
        const NativeRuntimeMemory& memory, const std::uint32_t address) {
        const auto bytes = memory.read_linear_range(address, 2);
        if (!bytes) return std::nullopt;
        return static_cast<std::uint16_t>((static_cast<std::uint16_t>((*bytes)[0]) << 8U)
            | (*bytes)[1]);
    }

    [[nodiscard]] static bool list_is_valid(const NativeRuntimeMemory& memory,
        const std::uint32_t address) {
        const auto list = memory.read_linear_range(address, 12);
        if (!list) return false;
        const auto read_header = [&list](const std::size_t offset) {
            return (static_cast<std::uint32_t>((*list)[offset]) << 24U)
                | (static_cast<std::uint32_t>((*list)[offset + 1U]) << 16U)
                | (static_cast<std::uint32_t>((*list)[offset + 2U]) << 8U)
                | static_cast<std::uint32_t>((*list)[offset + 3U]);
        };
        if (read_header(4) != 0) return false;
        const auto tail_sentinel = address + 4U;
        auto current = read_header(0);
        auto expected_predecessor = address;
        for (unsigned count = 0; count < 8; ++count) {
            const auto tail_predecessor = read_be32(memory, address + 8U);
            if (!tail_predecessor) return false;
            if (current == tail_sentinel) {
                return *tail_predecessor == expected_predecessor;
            }
            const bool guest_node = current >= guest_range_begin
                && current < guest_range_end;
            const bool source_port = current == title_port1_address
                || current == title_port2_address || current == main_stage_port_address;
            if ((!guest_node && !source_port) || current == address
                || current == address + 8U) {
                return false;
            }
            const auto predecessor = read_be32(memory, current + 4U);
            const auto successor = read_be32(memory, current);
            if (!predecessor || !successor || *predecessor != expected_predecessor) {
                return false;
            }
            expected_predecessor = current;
            current = *successor;
        }
        return false;
    }

    [[nodiscard]] static bool port_is_public(const NativeRuntimeMemory& memory,
        const std::uint32_t port_address) {
        const auto list_address = exec_base_address + port_list_offset;
        const auto list = memory.read_linear_range(list_address, 12);
        if (!list) return false;
        std::uint32_t current = read_be32(memory, list_address).value_or(0);
        const auto tail_sentinel = list_address + 4U;
        for (unsigned count = 0; count < 8 && current != tail_sentinel; ++count) {
            if (current == port_address) return true;
            current = read_be32(memory, current).value_or(tail_sentinel);
        }
        return false;
    }

    [[nodiscard]] static bool enqueue_node(NativeRuntimeMemory& memory,
        std::map<std::uint32_t, std::uint8_t>& writes,
        const std::uint32_t list_address, const std::uint32_t node_address,
        const std::int8_t priority) {
        const auto head = read_be32(memory, list_address);
        if (!head) return false;
        const auto tail_sentinel = list_address + 4U;
        auto current = *head;
        unsigned traversed = 0;
        while (current != tail_sentinel) {
            if (++traversed > 8) return false;
            const auto current_priority = memory.read_byte({
                NativeRuntimeAddressSpace::linear, std::nullopt, current + 9U});
            const auto next = read_be32(memory, current);
            if (!current_priority || !next) return false;
            // Kickstart 1.3 Enqueue advances across greater or equal
            // priorities, keeping equal-priority insertion stable.
            if (priority > static_cast<std::int8_t>(*current_priority)) break;
            current = *next;
        }
        const auto previous = read_be32(memory, current + 4U);
        if (!previous) return false;
        put32(writes, node_address, current);
        put32(writes, node_address + 4U, *previous);
        put32(writes, *previous, node_address);
        put32(writes, current + 4U, node_address);
        return true;
    }

    [[nodiscard]] static bool apply_writes(NativeRuntimeMemory& memory,
        std::string id, const std::map<std::uint32_t, std::uint8_t>& writes) {
        if (writes.empty()) return false;
        NativeRuntimeEffectBatch batch{std::move(id), true, {}};
        batch.effects.reserve(writes.size());
        for (const auto& [address, value] : writes) {
            batch.effects.push_back({batch.effects.size() + 1U,
                {NativeRuntimeAddressSpace::linear, std::nullopt, address},
                MemoryTransferElementWidth::byte, NativeRuntimeByteOrder::big_endian,
                value});
        }
        return memory.apply(batch).accepted;
    }

    std::uint64_t runtime_generation_ = 0;
    std::uint64_t sequence_ = 1;
    std::uint8_t ports_added_ = 0;
    std::uint8_t units_opened_ = 0;
    bool graph_installed_ = false;
    bool bootstrap_exec_base_pointer_installed_ = false;
    bool task_found_ = false;
    bool main_stage_task_found_ = false;
    bool main_stage_port_added_ = false;
    bool main_stage_unit_opened_ = false;
};

} // namespace eon
